class Solution {
    int[] parent;
    private int find(int value){
        return value==parent[value]?value:(parent[value]=find(parent[value]));
    }
    private void union(int a,int b){
        parent[find(a)]=find(b);
    }
    public boolean gcdSort(int[] nums){
        int maximum=Arrays.stream(nums).max().getAsInt();
        parent=new int[maximum+1];
        for(int i=0;i<=maximum;i++)parent[i]=i;
        for(int value:nums){
            int remaining=value;
            for(int factor=2;factor*factor<=remaining;factor++)if(remaining%factor==0){
                union(value,factor);
                while(remaining%factor==0)remaining/=factor;
            }
            if(remaining>1)union(value,remaining);
        }
        int[] sorted=nums.clone();
        Arrays.sort(sorted);
        for(int i=0;i<nums.length;i++)if(find(nums[i])!=find(sorted[i]))return false;
        return true;
    }
}

